-- PrioMeister – Locale.lua
-- Sprache: Das Addon ist auf Deutsch geschrieben, T(text) liefert den Text in der
-- eingestellten Sprache. Schlüssel ist der deutsche Text, EN die englische Fassung.
-- Gewählt wird beim Laden über die Option „Sprache“: automatisch nach der
-- Spielsprache (deDE: Deutsch, sonst Englisch), Deutsch oder Englisch.
-- Formate für priomeister.de bleiben immer deutsch: Export (Kopfzeile, Art, Status,
-- „an …“/„von …“), Kommentarzeile der Prioliste und Priocheck.

local _, ns = ...
ns = ns or {}

local EN = {}
ns.EN = EN
ns.lang = "de"

-- Text in der eingestellten Sprache; fehlt die Übersetzung, bleibt er deutsch.
-- ns.missing (nur in Tests) sammelt fehlende Übersetzungen.
function ns.T(text)
	if ns.lang == "en" and type(text) == "string" then
		local e = EN[text]
		if e then return e end
		if ns.missing then ns.missing[text] = true end
	end
	return text
end

-- Sprache aus der Einstellung ("auto", "de", "en") und der Spielsprache (GetLocale)
function ns.ResolveLanguage(setting, locale)
	if setting == "de" or setting == "en" then return setting end
	return (locale == "deDE") and "de" or "en"
end

-- Popups: Text und Knöpfe werden bei der Sprachwahl übersetzt
ns.popups = {}
function ns.Popup(name, def)
	def._de = { text = def.text, button1 = def.button1, button2 = def.button2, button3 = def.button3 }
	ns.popups[name] = def
	if StaticPopupDialogs then StaticPopupDialogs[name] = def end
	return def
end

function ns.SetLanguage(lang)
	ns.lang = (lang == "en") and "en" or "de"
	for _, def in pairs(ns.popups) do
		for k, v in pairs(def._de) do def[k] = ns.T(v) end
	end
end

